CREATE TABLE IF NOT EXISTS vexa_super_admins (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,role ENUM('owner','super_admin') NOT NULL DEFAULT 'super_admin',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,last_login_at TIMESTAMP NULL,PRIMARY KEY(id),UNIQUE KEY uq_vexa_super_admin_user(user_id),KEY idx_vexa_super_admin_active_role(is_active,role));
CREATE TABLE IF NOT EXISTS vexa_admin_audit_log (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,admin_id BIGINT UNSIGNED NOT NULL,action VARCHAR(128) NOT NULL,resource_type VARCHAR(128) NULL,resource_id VARCHAR(255) NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(512) NULL,metadata JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY idx_vexa_admin_audit_admin_time(admin_id,created_at),KEY idx_vexa_admin_audit_resource(resource_type,resource_id),KEY idx_vexa_admin_audit_action_time(action,created_at));
